import numpy as np
from rcb_client import Robot
r=Robot();o=r.get_obs(depth=True);cam='egocentric_mirrored_camera';K=np.array(r.spec()['cameras'][cam]['intrinsic_cv']);E=np.array(o.meta['cameras'][cam]['extrinsic_cv']);W=np.linalg.inv(np.vstack((E,[0,0,0,1])));d=o.last_depth[cam];im=o.last[cam]
for v in [100,110,120,130,140,150,160,170,180,190,200,210,220,230,240]:
 arr=[]
 for u in [100,120,140,160,180,200,220,240,260,280,300,320,340]:
  z=float(d[v,u]);
  if z>0:
   c=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]);p=W@c
   arr.append(f'{u}:{p[0]:.2f},{p[1]:.2f},{p[2]:.2f}')
 print(v,' | '.join(arr))
PY

