for x,y in [(.31,-.32),(.32,-.32),(.33,-.32),(.39,-.32),(.39,-.25),(.39,-.39),(.33,-.38),(.45,-.32)]:
 p=np.array([x,y,.03]);c=E[:,:3]@p+E[:,3];u=K[0,0]*c[0]/c[2]+K[0,2];v=K[1,1]*c[1]/c[2]+K[1,2];ui,vi=int(round(u)),int(round(v));z=float(d[vi,ui]);rgb=im[vi,ui];
 print((x,y),'pix',round(u,1),round(v,1),'camz',round(float(c[2]),3),'sample',z,rgb)
