python - <<'PY'
import numpy as np
from scipy import ndimage
from rcb_client import Robot
r=Robot();o=r.get_obs(depth=True);cam='egocentric_mirrored_camera';im=o.last[cam].astype(float); dep=o.last_depth[cam];K=np.array(r.spec()['cameras'][cam]['intrinsic_cv']);E=np.array(o.meta['cameras'][cam]['extrinsic_cv']);W=np.linalg.inv(np.vstack([E,[0,0,0,1]]));R,G,B=im.transpose(2,0,1)
colors={'green':(G>R*1.02)&(G>B*1.08)&(G>50),'yellow':(R>90)&(G>95)&(B<115)&(R/G>0.8)&(R/G<1.25),'orange':(R>120)&(G>55)&(R>G*1.18)&(B<100),'red':(R>90)&(R>G*1.25)&(R>B*1.2)}
rois={'lime_plate':('green',(205,105,250,160)),'orange_plate':('orange',(175,135,235,190)),'lime_far':('green',(485,168,550,238)),'lemon_far':('yellow',(335,105,390,163)),'lemon_near':('yellow',(335,153,395,209)),'orange_table':('orange',(416,116,480,178)),'pomegranate':('red',(355,170,442,254))}
for obj,(color,(x1,y1,x2,y2)) in rois.items():
 m=colors[color][y1:y2,x1:x2];labs,n=ndimage.label(m);parts=[]
 for lab in range(1,n+1):
  yy,xx=np.where(labs==lab)
  if len(xx)>15:parts.append((len(xx),xx+x1,yy+y1))
 if not parts:print(obj,'none');continue
 area,xx,yy=max(parts,key=lambda a:a[0]);z=dep[yy,xx]; good=z>0;xx=xx[good];yy=yy[good];z=z[good]
 cp=np.c_[(xx-K[0,2])*z/K[0,0],(yy-K[1,2])*z/K[1,1],z,np.ones(len(z))];pts=(W@cp.T).T[:,:3];med=np.median(pts,axis=0);q10,q90=np.percentile(pts,[10,90],axis=0)
 A=np.c_[2*pts,np.ones(len(pts))];b=(pts*pts).sum(1);s=np.linalg.lstsq(A,b,rcond=None)[0];c=s[:3];rad=np.sqrt(max(0,c@c+s[3]));
 print(obj,'area',area,'pix',np.round([xx.mean(),yy.mean()],1),'med',np.round(med,3),'q10',np.round(q10,3),'q90',np.round(q90,3),'fit',np.round(c,3),'r',round(rad,3))
PY

