import numpy as np
from scipy import ndimage
from scipy.optimize import least_squares
from rcb_client import Robot
r=Robot();o=r.get_obs(depth=True);cam='egocentric_mirrored_camera';im=o.last[cam].astype(float);dep=o.last_depth[cam];K=np.array(r.spec()['cameras'][cam]['intrinsic_cv']);E=np.array(o.meta['cameras'][cam]['extrinsic_cv']);W=np.linalg.inv(np.vstack([E,[0,0,0,1]]));R,G,B=im.transpose(2,0,1);m=(R>90)&(R>G*1.25)&(R>B*1.2);x1,y1,x2,y2=355,170,445,270; labs,n=ndimage.label(m[y1:y2,x1:x2]);
for lab in range(1,n+1):
 yy,xx=np.where(labs==lab)
 if len(xx)>200:
  xx=xx+x1;yy=yy+y1;z=dep[yy,xx];good=z>0;xx=xx[good];yy=yy[good];z=z[good];cp=np.c_[(xx-K[0,2])*z/K[0,0],(yy-K[1,2])*z/K[1,1],z,np.ones(len(z))];pts=(W@cp.T).T[:,:3];print('pix',xx.min(),yy.min(),xx.max(),yy.max(),xx.mean(),yy.mean(),'median',np.median(pts,0),'quant',np.percentile(pts,[10,90],0));
  pts=pts[np.linspace(0,len(pts)-1,min(300,len(pts))).astype(int)];med=np.median(pts,0);
  def fun(v):
   cx,cy,r=v;return np.linalg.norm(pts-np.array([cx,cy,.003+r]),axis=1)-r
  f=least_squares(fun,[.50,-.04,.055],bounds=([.2,-.5,.02],[.8,.5,.12]),loss='soft_l1',f_scale=.005);print('sphere',f.x)
  u,v=xx.mean(),yy.mean();ray=W[:3,:3]@np.array([(u-K[0,2])/K[0,0],(v-K[1,2])/K[1,1],1]);C=W[:3,3];t=(.058-C[2])/ray[2];print('center ray',C+t*ray)
